--**********************************
--武魂技能安装
--**********************************
function x900004_UseNowKfsSkill(sceneId,selfId)
	local nKfsDefinceID = LuaFnGetItemTableIndexByIndex(sceneId,selfId,110)	
	if nKfsDefinceID ~= 0 then
		local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,110);		
		if nKfsData_main ~= nil then
			local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
			if Pos1 ~= nil and Pos2 ~= nil then
				local nSkillSign = {
					strsub(nSkill,1,2),
					strsub(nSkill,3,4),
					strsub(nSkill,5,6)
				}
				for i = 1,3 do
					if x900004_Kfs_SkillTable[nSkillSign[i]] ~= nil and HaveSkill(sceneId,selfId,x900004_Kfs_SkillTable[nSkillSign[i]]) ~= 1 then
						AddSkill(sceneId,selfId,x900004_Kfs_SkillTable[nSkillSign[i]]);
					end
				end
			end
		end
	end
end
--**********************************
--武魂技能清洗
--**********************************
function x900004_UnNowKfsSkill(sceneId,selfId)
	local nKfsDefinceID = LuaFnGetItemTableIndexByIndex(sceneId,selfId,110)
	if nKfsDefinceID ~= 0 then
		local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,110);
		if nKfsData_main ~= nil then
			local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
			if Pos1 ~= nil and Pos2 ~= nil then
				local nSkillSign = {
					strsub(nSkill,1,2),
					strsub(nSkill,3,4),
					strsub(nSkill,5,6)
				}
				for i = 1,3 do
					if x900004_Kfs_SkillTable[nSkillSign[i]] ~= nil and HaveSkill(sceneId,selfId,x900004_Kfs_SkillTable[nSkillSign[i]]) == 1 then
						DelSkill(sceneId,selfId,x900004_Kfs_SkillTable[nSkillSign[i]]);
					end
				end
			end
		end
	end
	DispatchUICommand(sceneId,selfId, 20200427)
end
--**********************************
--武魂属性结算
--**********************************
function x900004_ComputeKfs(sceneId,selfId)
	local nStr,nSpr,nCon,nInt,nDex = 0,0,0,0,0
	local nIceAttr,nFireAttr,nLightAttr,nPosionAttr = 0,0,0,0
	local nIceDec,nFireDec,nLightDec,nPosionDec = 0,0,0,0
	local nIceSubDec,nFireSubDec,nLightSubDec,nPosionSubDec = 0,0,0,0
	local nIceSubDecL,nFireSubDecL,nLightSubDecL,nPosionSubDecL = 0,0,0,0
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,110);
	local nKfsDefinceID = LuaFnGetItemTableIndexByIndex(sceneId,selfId,110)
	if nKfsDefinceID ~= 0 and nKfsData_main ~= nil then
		local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
		if Pos1 ~= nil and Pos2 ~= nil then
			if x900004_Kfs_AttrType[nKfsDefinceID] ~= nil then
				--基础属性
				local nBaseAttr,nOldBaseAttr = Lua_KfsGetAttrAndOldAttr(1,tonumber(nGrow),x900004_Kfs_AttrType[nKfsDefinceID],tonumber(nLevel))
				nStr = nBaseAttr + nOldBaseAttr
				nBaseAttr,nOldBaseAttr = Lua_KfsGetAttrAndOldAttr(2,tonumber(nGrow),x900004_Kfs_AttrType[nKfsDefinceID],tonumber(nLevel))
				nSpr = nBaseAttr + nOldBaseAttr
				nBaseAttr,nOldBaseAttr = Lua_KfsGetAttrAndOldAttr(3,tonumber(nGrow),x900004_Kfs_AttrType[nKfsDefinceID],tonumber(nLevel))
				nCon = nBaseAttr + nOldBaseAttr
				nBaseAttr,nOldBaseAttr = Lua_KfsGetAttrAndOldAttr(4,tonumber(nGrow),x900004_Kfs_AttrType[nKfsDefinceID],tonumber(nLevel))
				nInt = nBaseAttr + nOldBaseAttr
				nBaseAttr,nOldBaseAttr = Lua_KfsGetAttrAndOldAttr(5,tonumber(nGrow),x900004_Kfs_AttrType[nKfsDefinceID],tonumber(nLevel))
				nDex = nBaseAttr + nOldBaseAttr
				--拓展属性
				local nAttrExType,nAttrExValue,nAttrSign = {},{},{}
				for i = 1,7 do
					nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
					nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
					nAttrSign[i] = nAttrExType[i]..nAttrExValue[i]
					if nAttrExType[i] == "A" then
						nIceAttr = nIceAttr + x900004_nAttrExTable[nAttrSign[i]][4]--nAttrExValue[i]
					end
					if nAttrExType[i] == "B" then
						nIceDec = nIceDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end	
					if nAttrExType[i] == "C" then
						nFireAttr = nFireAttr + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "D" then
						nFireDec = nFireDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "E" then
						nLightAttr = nLightAttr + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "F" then
						nLightDec = nLightDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "G" then
						nPosionAttr = nPosionAttr + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					--减抗
					if nAttrExType[i] == "H" then
						nPosionDec = nPosionDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "I" then
						nIceSubDec = nIceSubDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "J" then
						nFireSubDec = nIceSubDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "K" then
						nLightSubDec = nIceSubDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "L" then
						nPosionSubDec = nIceSubDec + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					--减抗下限
					if nAttrExType[i] == "M" then
						nIceSubDecL = nIceSubDecL + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "N" then
						nFireSubDecL = nFireSubDecL + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "O" then
						nLightSubDecL = nLightSubDecL + x900004_nAttrExTable[nAttrSign[i]][4]
					end
					if nAttrExType[i] == "P" then
						nPosionSubDecL = nPosionSubDecL + x900004_nAttrExTable[nAttrSign[i]][4]
					end
				end
				--
				--武魂外观
				if LuaFnGetItemTableIndexByIndex( sceneId, selfId, 103 ) ~= 0 then
					if x900004_Kfs_AttrType[nKfsDefinceID] == nil then
						LuaFnSetEquipVisual(sceneId,selfId,103,0);
						LuaFnRefreshHumanObject(sceneId,selfId)                        					
					else
						local nNowKfsVisual = LuaFnGetEquipVisual(sceneId,selfId,103)
						local nKfsVisualID = x900004_g_KFSVisual[x900004_Kfs_AttrType[nKfsDefinceID]][tonumber(nMagic) + 1]
						LuaFnSetEquipVisual(sceneId,selfId,103,nKfsVisualID-2000);						
						LuaFnRefreshHumanObject(sceneId,selfId)
					end				    		
				end
				x900004_RefreshKfs(sceneId,selfId);--提醒客户端武魂属性刷新了
			end
			else
						if nMagic == nil then
						   nMagic = 0
						end
						local nKfsVisualID = x900004_g_KFSVisual[x900004_Kfs_AttrType[nKfsDefinceID]][tonumber(nMagic) + 1]
						LuaFnSetEquipVisual(sceneId,selfId,103,nKfsVisualID-2000);						
						LuaFnRefreshHumanObject(sceneId,selfId)
		end
		else
						--武魂外观
				if LuaFnGetItemTableIndexByIndex( sceneId, selfId, 103 ) ~= 0 then
					if x900004_Kfs_AttrType[nKfsDefinceID] == nil then
						LuaFnSetEquipVisual(sceneId,selfId,103,0);
						LuaFnRefreshHumanObject(sceneId,selfId)
                    end						
				end
	end

	--x900004_NotifyTip( sceneId, selfId, "nDex "..nDex )	
	return nStr,nSpr,nCon,nInt,nDex,nIceAttr,nFireAttr,nLightAttr,nPosionAttr,nIceDec,nFireDec,nLightDec,nPosionDec,nIceSubDec,nFireSubDec,nLightSubDec,nPosionSubDec,nIceSubDecL,nFireSubDecL,nLightSubDecL,nPosionSubDecL
end
--**********************************
--武魂技能升级
--**********************************
function x900004_KfsSkillUp(sceneId,selfId,nKfsPos,nMaterialPos,nIndex,nType)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nMaterialPos == nil or nType == nil or nIndex == nil then
		return
	end
	--看看材料是不是上锁了
	if LuaFnIsItemLocked(sceneId, selfId, nMaterialPos) ~= 0 then
		x900004_NotifyTip( sceneId, selfId,  "#{WHYH_161121_68}" )
		return
	end
	if nIndex < 0 or nIndex > 2 then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_72}" )	
		return
	end
	nIndex = nIndex + 1
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_70}" )	
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_71}" )	
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 ~= nil and Pos2 ~= nil then
		local nSkillType,nSkillValue = {},{}
		local nSkillNum = 0;
		local nSkillSign = {}
		for i = 1,3 do
			nSkillType[i] = strsub(nSkill, (i*2) - 1,(i*2) - 1)
			if nSkillType[i] ~= "0" then
				nSkillNum = nSkillNum + 1;
			end
			nSkillValue[i] = tonumber(strsub(nSkill, i*2,i*2))
			nSkillSign[i] = nSkillType[i]..nSkillValue[i]
		end
		if nSkillNum == 0 then
			x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_71}" )	
			return
		end
		if nSkillValue[nIndex] >= 6 then --目前最高开放6级，其实最高应该是8级，但是为了符合策划 (滑.稽)，想开6级以上的缺的自己补吧
			x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_73}" )
			return
		end
		local upSkillID,needItem,nMoney = Lua_GetkfsSkillLevelUp(x900004_Kfs_SkillTable[nSkillSign[nIndex]]);
--		x900004_NotifyTip( sceneId, selfId,"upSkillID "..upSkillID)
		if upSkillID == nil or upSkillID == 0 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_65}")  --请选择需要升级的技能
			return
		end
		-- 武魂的当前技能是否已提升至最高级
		if upSkillID == -1 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_66}")  --该技能已经达到最高等级，不能继续升级！
			return
		end
		local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
		if nMoneySelf < nMoney then
			x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
			return
		end
		if needItem ~= nil and needItem <= 0 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_66}")
			return
		end
		local needItemBind = x900004_GetBindItemIndex(needItem)
		if needItemBind ~= nil and needItemBind <= 0 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_66}")
			return
		end
		local nItemID = LuaFnGetItemTableIndexByIndex(sceneId,selfId,nMaterialPos)
			local needItemName = GetItemName(sceneId,needItem)
			local bRet,strSkillName = LuaFnDelAvailableItem(sceneId,selfId,needItem,1),"#{XYJ_KFS_SKILL_NAME_"..x900004_Kfs_SkillTableEx[upSkillID].."}"
			if bRet ~= 1 then
				local tips = format("升级至%s#H技能需要使用一颗%s#H。您当前放入的魂冰珠不符合升级条目的需要，请重新放置。", strSkillName, needItemName)
				x900004_NotifyTip( sceneId, selfId,tips)
				return
			end
		
		--全部校验都通过了
		nSkillValue[nIndex] = nSkillValue[nIndex] + 1
		local nFinalKfsSkillData = "";
		for i = 1,3 do
			nFinalKfsSkillData = nFinalKfsSkillData..nSkillType[i]..nSkillValue[i]
		end
		local nFinalKfsData = ""
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nExAttr..nFinalKfsSkillData
		nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
		LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
		--数据存储完毕，恭喜玩家了
		LuaFnDelAvailableItem(sceneId,selfId,needItem,1)
		LuaFnCostMoney( sceneId, selfId, nMoney);
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_28}");
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		--3级以上发小喇叭
		if nSkillValue[nIndex] >= 3 then
			local nGlobalText = format("#P皇天不负有心人，辛苦的付出终有回报。#G#{_INFOUSR%s}#P经过不懈的努力，终于使%s学会了#G%s#P！",
				GetName(sceneId,selfId),
				GetItemName(sceneId,LuaFnGetItemTableIndexByIndex(sceneId,selfId,nKfsPos)),
				"#{XYJ_KFS_SKILL_NAME_"..nSkillType[nIndex]..nSkillValue[nIndex].."}")
			AddGlobalCountNews( sceneId,nGlobalText);
		end
	else
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_71}" )	
		return
	end
end
-- 获得所需的材料对应的绑定材料
function x900004_GetBindItemIndex(needItem)
	if needItem == nil or needItem <= 0 then
		return 0
	end

	-- 所需材料id对应的索引
	local needLevelIndex = 0
	for i=1, getn(x900004_g_HunBing) do
		if x900004_g_HunBing[i] == needItem then
			needLevelIndex = i
			break
		end
	end
	if needLevelIndex == 0 then
		return 0
	end
	
	-- 所需材料对应的绑定材料
	return x900004_g_HunBing_Bind[needLevelIndex]
end
--**********************************
--武魂技能重洗替换
--**********************************
function x900004_SaveWashKfsSkill(sceneId,selfId,nKfsPos)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil then
		return
	end
	local nSavePos = GetMissionData(sceneId,selfId,MD_KFS_REWASH_POS)
	--临时数据重做 2019-11-14 21:57:03 
	local nTempSign = "KFS"..LuaFnObjId2Guid(sceneId,selfId)
	local nSaveSkill = LuaFnGetGlobalDataString(sceneId,selfId,nTempSign)
	local nTempDataLen = GetMissionData(sceneId,selfId,MD_TEMPDATA_LONG)
	if nTempDataLen < 1 then
		x900004_NotifyTip(sceneId,selfId,"本次重洗失败")
		return
	end
	if nSaveSkill == nil or nSaveSkill == "" then
		x900004_NotifyTip(sceneId,selfId,"本次重洗失败")
		return
	end
	nSaveSkill = strsub(nSaveSkill,1,nTempDataLen)
	SetMissionData(sceneId,selfId,MD_TEMPDATA_LONG,0)
	
	if nSaveSkill == nil or nSaveSkill == "" then
		x900004_NotifyTip( sceneId, selfId, "服务端数据异常，本次重洗失败，请再次尝试或联系GM运营团队" )	
		return
	end
	
	if nKfsPos ~= nSavePos then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_48}" )	
		return
	end
	
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_49}" )	
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 ~= nil and Pos2 ~= nil then
		local nFinalKfsData = ""
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nExAttr..nSaveSkill
		nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
		LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
		x900004_NotifyTip( sceneId, selfId,"替换武魂技能成功！");
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	end
end
