function x900004_AskWashKfsSkill(sceneId,selfId,nKfsPos,nCheck)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nCheck == nil then
		return
	end
	if nCheck ~= 0 and nCheck ~= 1 then
		return
	end
	
	if LuaFnGetAvailableItemCount(sceneId,selfId,x900004_KfsItem_YiHunShi[1]) < 10 and nCheck == 1 then --LuaFnMtl_GetCostNum(sceneId, selfId,x900004_KfsItem_YiHunShi[1],x900004_KfsItem_YiHunShi[2],x900004_KfsItem_YiHunShi[3]) < 1 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_KfsItem_YiHunShi[1],10,nCheck);
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_48}" )	
		return
	end
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < 50000 then
		x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_49}" )	
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 ~= nil and Pos2 ~= nil then
		local nSkillType,nSkillValue = {},{}
		local nSkillNum = 0;
		for i = 1,3 do
			nSkillType[i] = strsub(nSkill, (i*2) - 1,(i*2) - 1)
			if nSkillType[i] ~= "0" then
				nSkillNum = nSkillNum + 1;
			end
			nSkillValue[i] = tonumber(strsub(nSkill, i*2,i*2))
		end
		if nSkillNum == 0 then
			x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_49}" )	
			return
		end
		--2019-10-18 20:12:47  武魂技能特征修正
		for i = 1,nSkillNum do
			if i == 1 then
				local nRandIndex = random(1,getn(x900004_g_PassiveSkill))
				nSkillType[i] = x900004_g_PassiveSkill[nRandIndex]
			else
				local nRandIndex = random(1,getn(x900004_g_ActiveSkill))
				nSkillType[i] = x900004_g_ActiveSkill[nRandIndex]
				while nSkillType[i] == nSkillType[i - 1] do
					nRandIndex = random(1,getn(x900004_g_ActiveSkill))
					nSkillType[i] = x900004_g_ActiveSkill[nRandIndex]
				end
			end
		end
		local nFinalKfsSkillData = "";
		for i = 1,3 do
			nFinalKfsSkillData = nFinalKfsSkillData..nSkillType[i]..nSkillValue[i]
		end		
		local nRet = LuaFnDelAvailableItem(sceneId,selfId,x900004_KfsItem_YiHunShi[1],10)--LuaFnMtl_CostMaterial(sceneId,selfId,1,x900004_KfsItem_YiHunShi[1],x900004_KfsItem_YiHunShi[2],x900004_KfsItem_YiHunShi[3])
		if nRet ~= 1 then
			BeginEvent( sceneId )
			AddText( sceneId, "物品扣除失败！请您检查您的背包以准备足够的物品！" )--这里就不补充StringTable_GetData函数了，那么麻烦干嘛。。
			EndEvent( sceneId )
			DispatchMissionTips( sceneId, selfId )
			return
		end
		LuaFnCostMoney( sceneId, selfId, 50000);
		
		--修正临时存储 2019-11-14 21:49:05 
		local nTempSign = "KFS"..LuaFnObjId2Guid(sceneId,selfId)
		SetMissionData(sceneId,selfId,MD_TEMPDATA_LONG,strlen(nFinalKfsSkillData))
		LuaFnSetGlobalDataString(sceneId,selfId,nTempSign,nFinalKfsSkillData)		
		
		SetMissionData(sceneId,selfId,MD_KFS_REWASH_POS,nKfsPos)
		BeginUICommand(sceneId)
			UICommand_AddString( sceneId,nFinalKfsSkillData)
		EndUICommand(sceneId )
		DispatchUICommand(sceneId,selfId, 1000000033)
		x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_55}");
	else
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_49}" )	
		return
	end
end
