function x900004_KfsStudySkill(sceneId,selfId,nKfsPos)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil then
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId, "#{WHXCZL_091026_03}" )	
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId, "#{WH_090729_23}" )	
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 ~= nil and Pos2 ~= nil then
		--nLevel = tonumber(nLevel) --切记
		local nCanHaveSkill = 0;
		if tonumber(nLevel) >= 40 and tonumber(nLevel) < 70 then
			nCanHaveSkill = 1;
		elseif tonumber(nLevel) >= 70 and tonumber(nLevel) < 90 then
			nCanHaveSkill = 2;
		elseif tonumber(nLevel) >= 90 then
			nCanHaveSkill = 3;
		end
		local nSkillType,nSkillValue = {},{}
		local nSkillNum = 0;
		local nSkillStart = 0;
		for i = 1,3 do
			nSkillType[i] = strsub(nSkill, (i*2) - 1,(i*2) - 1)
			if nSkillType[i] ~= "0" then
				nSkillNum = nSkillNum + 1;
			else
				if nSkillStart == 0 then
					nSkillStart = i;
				end
			end
			nSkillValue[i] = tonumber(strsub(nSkill, i*2,i*2))
		end
		if nSkillNum >= nCanHaveSkill then
			x900004_NotifyTip( sceneId, selfId, "#{WH_090729_23}" )	--对不起，你的武魂还没有达到领悟下一个技能的级别
			return
		end
		local needMoney = 0
		if nSkillNum == 0 then
			needMoney = 50000			--第一个技能5金
		elseif 	nSkillNum == 1 then
			needMoney = 100000			--第二个技能10金
		elseif 	nSkillNum == 2 then
			needMoney = 150000			--第三个技能15金
		end
		local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
		if nMoneySelf < needMoney then
			x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
			return
		end
		--2019-10-18 20:12:47  武魂技能特征修正
		if nSkillStart == 1 then
			local nRandIndex = random(1,getn(x900004_g_PassiveSkill))
			nSkillType[nSkillStart] = x900004_g_PassiveSkill[nRandIndex]
		else
			local nRandIndex = random(1,getn(x900004_g_ActiveSkill))
			nSkillType[nSkillStart] = x900004_g_ActiveSkill[nRandIndex]
			while nSkillType[nSkillStart] == nSkillType[nSkillStart - 1] do
				nRandIndex = random(1,getn(x900004_g_ActiveSkill))
				nSkillType[nSkillStart] = x900004_g_ActiveSkill[nRandIndex]
			end
		end
		nSkillValue[nSkillStart] = 1;
		
		local nFinalKfsSkillData = "";
		for i = 1,3 do
			nFinalKfsSkillData = nFinalKfsSkillData..nSkillType[i]..nSkillValue[i]
		end
		local nFinalKfsData = ""
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nExAttr..nFinalKfsSkillData
		nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
		--x900004_NotifyTip( sceneId, selfId,"nFinalKfsData "..nFinalKfsData);
		LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
		LuaFnCostMoney( sceneId, selfId, needMoney);
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_24}");
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	end
end
function Inspectionitem(sceneId, selfId,n_ItemID,u_ItemID,n_number)
local itemcnom = LuaFnGetAvailableItemCount(sceneId, selfId, n_ItemID)
local itemcnom2 = 0
if itemcnom < n_number then
itemcnom2 = LuaFnGetAvailableItemCount(sceneId, selfId, u_ItemID)
end
if itemcnom + itemcnom2 < n_number then
	BeginEvent(sceneId)
	   AddText(sceneId,"#{_ITEM"..tostring(n_ItemID).."}不足"..n_number.."个");
	EndEvent(sceneId)
	DispatchMissionTips(sceneId,selfId)	
return 0
end
local myret = 1 
local myret2 = 1
if itemcnom >= n_number then
myret = LuaFnDelAvailableItem(sceneId,selfId,n_ItemID,n_number)
else
myret = LuaFnDelAvailableItem(sceneId,selfId,n_ItemID,itemcnom)
end
if itemcnom2 ~= 0 then
myret2 = LuaFnDelAvailableItem(sceneId,selfId,u_ItemID,n_number-itemcnom)
end
if myret ~= 1 and myret2 ~= 1 then
	BeginEvent(sceneId)
		AddText(sceneId,"扣除#{_ITEM"..tostring(n_ItemID).."}失败");
	EndEvent(sceneId)
	DispatchMissionTips(sceneId,selfId)		
  return 0
end
  return 1
end
