function x900004_KfsChangeMagic(sceneId,selfId,nKfsPos,nIndex,nCheck)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nIndex == nil or nCheck == nil then
		return
	end
	if nCheck ~= 0 and nCheck ~= 1 then
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId, "#{WH_090729_13}" )	
		return
	end
	if nIndex < 1 or nIndex > 4 then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_103}");
		return
	end
	if LuaFnGetAvailableItemCount(sceneId,selfId,x900004_KfsItem_YiXiangDan[1]) < 1 then --LuaFnMtl_GetCostNum(sceneId, selfId,x900004_KfsItem_YiXiangDan[1],x900004_KfsItem_YiXiangDan[2],x900004_KfsItem_YiXiangDan[3]) < 1 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_KfsItem_YiXiangDan[1],1,nCheck);
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_101}");
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 == nil or Pos2 == nil then
		x900004_NotifyTip( sceneId, selfId,  "装备数据异常，请联系GM运营团队" )
		return
	end
	if nIndex == tonumber(nMagic) then
		x900004_NotifyTip( sceneId, selfId, "#{WHYH_161121_104}");
		return
	end
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < 50000 then
        x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
        return
	end
	nMagic = nIndex
	local nFinalKfsData = ""
	nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nExAttr..nSkill
	nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
	local nRet = LuaFnDelAvailableItem(sceneId,selfId,x900004_KfsItem_YiXiangDan[1],1)--LuaFnMtl_CostMaterial(sceneId,selfId,1,x900004_KfsItem_YiXiangDan[1],x900004_KfsItem_YiXiangDan[2],x900004_KfsItem_YiXiangDan[3])
	if nRet ~= 1 then
		BeginEvent( sceneId )
		AddText( sceneId, "背包物品不存在或已锁定" )
		EndEvent( sceneId )
		DispatchMissionTips( sceneId, selfId )
		return
	end	
	LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
	LuaFnCostMoney( sceneId, selfId, 50000);
	x900004_NotifyTip( sceneId, selfId,x900004_Kfs_Magic[nIndex]);
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
end
