--武魂拓展属性升级
--**********************************
function x900004_KfsAttrExLevelUp(sceneId,selfId,nKfsPos,nMaterialPos,nIndex,nType)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nMaterialPos == nil or nIndex == nil or nType == nil then
		return
	end
	if nIndex < 1 or nIndex > 10 then
		x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_41}" )
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId,"ERROR:NULL" )
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 == nil or Pos2 == nil then
		x900004_NotifyTip( sceneId, selfId,  "装备数据异常，请联系GM运营团队" )
		return
	end
	local needItem,needMoney = Lua_GetKfsFixAttrEx(nExAttr,100 + nIndex)
	if nType == 0 then
		if nKfsMainPoint ~= 10 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_40}" ) --这里字典不一样，要分开使用
			return
		end
		local nKfsID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nMaterialPos )
		if nKfsID ~= needItem then
			x900004_NotifyTip( sceneId, selfId,"#{WH_xml_XX(98)}"..GetItemName(sceneId,needItem))
			return
		end
		local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
		if nMoneySelf < needMoney then
			x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
			return
		end
		local nAttrExType,nAttrExValue = {},{}
		local nAttrExNum = 0;
		for i = 1,7 do
			nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
			nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
		end
		if nAttrExValue[nIndex] == 8 then
			x900004_NotifyTip( sceneId, selfId,  "#{WHYH_161121_42}" )
			return
		end
		--最高开放8级
		if nAttrExValue[nIndex] >= tonumber(nExLevel) then
		    x900004_NotifyTip( sceneId, selfId,  "当前合成等级只能强化至"..nAttrExValue[nIndex].."级。" )
			return
		end
			nAttrExValue[nIndex] = nAttrExValue[nIndex] + 1;
--		end
		if LuaFnGetAvailableItemCount(sceneId,selfId,needItem) < 1 then
		   x900004_NotifyTip( sceneId, selfId,"#{WH_xml_XX(98)}"..GetItemName(sceneId,needItem))
		   return
		end
		local nFinalKfsAttrData = "";
		for i = 1,7 do
			nFinalKfsAttrData = nFinalKfsAttrData..nAttrExType[i]..nAttrExValue[i]
		end
		local nFinalKfsData = ""
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nFinalKfsAttrData..nSkill
		nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
		
		LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
		LuaFnCostMoney( sceneId, selfId, needMoney);
		-- LuaFnEraseItem(sceneId,selfId,nMaterialPos);--既然能重叠物品，就不适用这种删除道具的函数
		LuaFnDelAvailableItem(sceneId,selfId,needItem,1)
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_32}");
		LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		--4级以上小喇叭
		if nAttrExValue[nIndex] > 4 then
			local nGlobalText = format("#H武惊日月，魂慑乾坤！#G#{_INFOUSR%s}#H在#G大理#{_INFOAIM140,195,2,无崖子}#R无崖子#H处通过武魂技能#G提升#H之法，终于使%s学会了#G%s#H！",
				GetName(sceneId,selfId),
				GetItemName(sceneId,LuaFnGetItemTableIndexByIndex(sceneId,selfId,nKfsPos)),
				Lua_GetKfsFixAttrEx(nAttrExType[nIndex]..nAttrExValue[nIndex]))
			AddGlobalCountNews( sceneId,nGlobalText);
		end
	elseif nType == 1 then
		--快捷提升
		if nKfsMainPoint ~= 10 then
			x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_33}" ) --这里字典不一样，要分开使用
			return
		end
		x900004_NotifyTip( sceneId, selfId,"快捷提升暂不开放" )
		return
	end
end
--**********************************
--增加武魂拓展属性栏
--**********************************
function x900004_AddKfsSlot(sceneId,selfId,nKfspos,nMaterialPos,nCheck)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	local iscommok = 0
	for i = 0,1 do
	  if LuaFnGetAvailableItemCount(sceneId,selfId,20310158+i,1) < 1 then
	     iscommok = iscommok + 1
	  end
	end
	if iscommok == 2 then
	   x900004_NotifyTip( sceneId, selfId,"需要麟木箭或破天箭")
	   return
	end
	if nKfspos == nil or nMaterialPos == nil or nCheck == nil then
		return
	end
	if nCheck ~= 0 and nCheck ~= 1 then
		return
	end
	if nMaterialPos == -1 and nCheck == 1 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_INDEX_SLOT_ITEM1,1,nCheck)
		return
	end
	local nKfsID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nMaterialPos )
	if nKfsID == 0 and nCheck == 1 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_INDEX_SLOT_ITEM1,1,nCheck)
		return
	end
	if nKfsID ~=  x900004_INDEX_SLOT_ITEM1 and nKfsID ~= x900004_INDEX_SLOT_ITEM2 then
		x900004_NotifyTip( sceneId, selfId,"#{WHYH_161121_134}") --此处只能放入麟木箭、破天剑
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, nMaterialPos) ~= 0 then
		x900004_NotifyTip( sceneId, selfId,  "#{WHYH_161121_38}" )
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfspos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_13}" )
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfspos);
	local Pos1,Pos2,comLv,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if tonumber(comLv) ~= nil and tonumber(nExAttrNum) ~= nil and tonumber(nExAttrNum) >= tonumber(nExLevel) then
		if tonumber(nExAttrNum) == 10 then
			x900004_NotifyTip( sceneId, selfId,"#{WH_090817_13}") -- 武魂的扩展属性栏数已经到达最大值10栏。
		else
			x900004_NotifyTip( sceneId, selfId,"#{WH_090729_50}") -- 该武魂不能开辟新的属性栏。提升灵力等级后，可以开辟新的属性栏。
		end
		return
	end
	local needMoney = Lua_GetBagKfsSlotMoney(tonumber(nExAttrNum));
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < needMoney then
        x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
        return
	end
	if nKfsData_main == nil then --这种情况应该是不存在的
		x900004_NotifyTip( sceneId, selfId,  "武魂等级必须大于1级才可开辟新的拓展属性栏" )
		return
	end
	local nFinalKfsData = ""
	local EquipXiuFu = "&W6022001000000100000000000000000000"
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 ~= nil and Pos2 ~= nil then
		nExAttrNum = tonumber(nExAttrNum) + 1
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..tostring(nExAttrNum)..nExAttr..nSkill
		nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
	else--有其余字符，但是没武魂字符。
		Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(EquipXiuFu,x900004_KfsDataVale)
		nExAttrNum = tonumber(nExAttrNum) + 1
		nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..tostring(nExAttrNum)..nExAttr..nSkill
		nFinalKfsData = nKfsData_main..nFinalKfsData
	end
	LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfspos,nFinalKfsData);
	LuaFnCostMoney( sceneId, selfId, needMoney);
	LuaFnEraseItem(sceneId,selfId,nMaterialPos);
	--LuaFnDelAvailableItem(sceneId,selfId,nKfsID,1);
	x900004_NotifyTip( sceneId, selfId,"#{WH_090729_55}");
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
end
