--**********************************
--武魂拓展属性删除
--**********************************
function x900004_KfsAttrExDelete(sceneId,selfId,nKfsPos,nIndex)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nIndex == nil then
		return
	end
	if nIndex < 1 or nIndex > 10 then
		x900004_NotifyTip( sceneId, selfId, "#{WH_090729_67}" )	
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_13}" )
		return
	end
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < 1000 then
        x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
        return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_57}") --该武魂没有扩展属性
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 == nil or Pos2 == nil then
		x900004_NotifyTip( sceneId, selfId,  "装备数据异常，请联系GM运营团队" )
		return
	end
	local nAttrExType,nAttrExValue = {},{}
	local nAttrExNum = 0;
	for i = 1,7 do
		nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
		if nAttrExType[i] ~= "0" then
			nAttrExNum = nAttrExNum + 1;
		end
		nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
	end
	if nAttrExNum == 0 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_57}") -- 该武魂没有扩展属性
		return
	end
	nAttrExType[nIndex] = "0";
	nAttrExValue[nIndex] = 0;
	
	local nFinalKfsAttrData = "";
	for i = 1,7 do
		nFinalKfsAttrData = nFinalKfsAttrData..nAttrExType[i]..nAttrExValue[i]
	end
	local nFinalKfsData = ""
	nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nFinalKfsAttrData..nSkill
	nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
	
	LuaFnCostMoney( sceneId, selfId, 1000);
	LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
	x900004_NotifyTip( sceneId, selfId,"#{WH_090729_58}")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
end
--**********************************
--武魂拓展属性学习
--**********************************
function x900004_KfsAttrExStudy(sceneId,selfId,nKfsPos,nBookPos)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nBookPos == nil then
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, nBookPos) ~= 0 then
		x900004_NotifyTip( sceneId, selfId,  "#{WHYH_161121_38}" )
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsPos )
	if nKfsMainPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_13}" )
		return
	end
	local nKfsBookID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nBookPos )
	if x900004_KfsAttrExBook[nKfsBookID] == nil then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_20}" )
		return
	end
	if LuaFnIsItemAvailable( sceneId, selfId,nBookPos) ~= 1 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_20}")
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsPos);
	if nKfsData_main == nil then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_56}") -- 需要有空余的属性栏，才能学习扩展属性。
		return
	end
	local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
	if Pos1 == nil or Pos2 == nil then
		x900004_NotifyTip( sceneId, selfId,  "装备数据异常，请联系GM运营团队" )
		return
	end
	local nStartIndex = 0;
	local nAttrExType,nAttrExValue = {},{}
	local nAttrExNum = 0;
	for i = 1,7 do
		nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
		if nAttrExType[i] ~= "0" then
			nAttrExNum = nAttrExNum + 1;
		else
			if nStartIndex == 0 then
				nStartIndex = i --何处为空
			end
		end
		nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
	end
	--nStartIndex = nStartIndex + nAttrExNum
	if nAttrExNum >= tonumber(nExAttrNum) and tonumber(nExAttrNum) >= 0 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_56}") -- 需要有空余的属性栏，才能学习扩展属性。
		return
	end
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < 80000 then
        x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
        return
	end
	nAttrExType[nStartIndex] = x900004_KfsAttrExBook[nKfsBookID];
	--是否重复校验
	local nPos_1,nPos_2 = strfind(nExAttr,nAttrExType[nStartIndex])
	if nPos_1 ~= nil or nPos_2 ~= nil then
	 	x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_66}" )
	    return
	end
	nAttrExValue[nStartIndex] = 1;
	local nFinalKfsAttrData = "";
	for i = 1,7 do
		nFinalKfsAttrData = nFinalKfsAttrData..nAttrExType[i]..nAttrExValue[i]
	end
	local nFinalKfsData = ""
	nFinalKfsData = "&W"..nGrow..nExLevel..nLevel..nKfsExp..nMagic..nExAttrNum..nFinalKfsAttrData..nSkill
	nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
	
	LuaFnCostMoney( sceneId, selfId, 80000);
	LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsPos,nFinalKfsData);
	LuaFnEraseItem(sceneId,selfId,nBookPos)
	x900004_NotifyTip( sceneId, selfId,"#{WH_090729_61}")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
end
--**********************************
--武魂合成
--**********************************
function x900004_KfsCompoud(sceneId,selfId,nKfsMain,nKfsCom)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsMain == nil or nKfsCom == nil then
		return
	end
	if LuaFnIsItemLocked(sceneId, selfId, nKfsCom) ~= 0 then
		x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_15}" )
		return
	end
	local nKfsMainPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsMain )
	local nKfsComPoint = LuaFnGetBagEquipType( sceneId, selfId, nKfsCom )
	if nKfsMainPoint ~= 10 or nKfsComPoint ~= 10 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_13}" )
		return
	end
	local gem_count = GetGemEmbededCount(sceneId,selfId,nKfsCom)
	if gem_count > 0 then
		x900004_NotifyTip( sceneId, selfId,"#{WH_20090904_01}")	--WH_20090904_01 镶嵌有宝石的武魂不能作为合成材料！
		return
	end
	local _,nKfsData_main = LuaFnGetItemCreator(sceneId,selfId,nKfsMain);
	local _,nKfsData_sub = LuaFnGetItemCreator(sceneId,selfId,nKfsCom);
	if nKfsData_sub ~= nil and strfind(nKfsData_sub,"&DW") ~= nil then
		x900004_NotifyTip( sceneId, selfId,"#{ZBDW_091105_17}")	--有雕纹的武魂不能作为材料武魂
		return
	end
	local _,main_lv = x900004_LuaGetKfsAttrData(sceneId,selfId,nKfsData_main)
	local _,sub_lv = x900004_LuaGetKfsAttrData(sceneId,selfId,nKfsData_sub)
	if  main_lv ~= nil and sub_lv ~= nil and main_lv ~= sub_lv then 
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_17}")  --参与合成的武魂灵力等级需要等于要提升灵力等级的武魂
		return
	end
	if main_lv == nil or main_lv >= 8 then
		x900004_NotifyTip( sceneId, selfId,"8级以上的武魂的合成暂未开放。")  --5级以上合成暂不开放。
		return
	end
	local needMoney = 0
	if main_lv ~= nil and main_lv > 0 and main_lv < 10 then
		needMoney = x900004_m_Money_COMPOUND[main_lv]
	end
	local nMoneySelf = GetMoneyJZ(sceneId,selfId) + GetMoney(sceneId,selfId)
	if nMoneySelf < needMoney then
        x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_18}" )
        return
	end
	main_lv = main_lv + 1
	local nFinalKfsData = ""
	if nKfsData_main == nil then
		nFinalKfsData = "&W6022001000000100000000000000000000"
	else
		local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData_main,x900004_KfsDataVale)
		--x900004_KfsDataVale = "&W(%w%w%w)(%w)(%w%w%w)(%w%w%w%w%w)(%w)(%w)("..strrep("%w",14)..")".."("..strrep("%w",6)..")"
		--属相部分
		if Pos1 ~= nil and Pos2 ~= nil then--有字符，和武魂字符存在
			if main_lv == 5 then
				local rand = random(1,4)
				nMagic = rand
				x900004_NotifyTip( sceneId, selfId,x900004_Kfs_Magic[nMagic])
			end
			nFinalKfsData = "&W"..nGrow..main_lv..nLevel..nKfsExp..nMagic..nExAttrNum..nExAttr..nSkill
			nFinalKfsData = gsub(nKfsData_main,x900004_KfsDataVale,nFinalKfsData)
		else--有字符，但是武魂字符不存在
            nFinalKfsData = nKfsData_main.."&W6022001000000100000000000000000000"
		end
	end
	LuaFnCostMoney( sceneId, selfId, needMoney);
	LuaFnSetEquipItemCreatorEx(sceneId, selfId,nKfsMain,nFinalKfsData);
	--设置绑定状态
	if LuaFnGetItemBindStatus(sceneId,selfId,nKfsCom) == 1 then
	    LuaFnItemBind(sceneId,selfId,nKfsMain)
	end
	LuaFnEraseItem(sceneId,selfId,nKfsCom)
	x900004_NotifyTip( sceneId, selfId,"#{WH_090729_19}")
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
end
--**********************************
--武魂延寿
--**********************************
function x900004_AddKfsLife(sceneId,selfId,nKfsPos,nMaiterialPos,nCheck)
	if IsPilferLockFlag(sceneId,selfId) <= 0 then
		x900004_NotifyTip( sceneId, selfId, "#{OR_PILFER_LOCK_FLAG}" )	
		return
	end
	if nKfsPos == nil or nMaiterialPos == nil or nCheck == nil then
		return
	end
	if nCheck ~= 0 and nCheck ~= 1 then
		return
	end
	if nMaiterialPos == -1 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_KfsItem_YanShouDan,1,nCheck)
		return
	end
	local nKfsID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, nMaiterialPos )
	if nKfsID == 0 then
		LuaFnBuyNotEnoughMaterial(sceneId,selfId,x900004_KfsItem_YanShouDan,1,nCheck)
		return
	end
	if nKfsID == x900004_KfsItem_YanShouDan then
		local ret = DoHighRepair( sceneId, selfId, nKfsPos, 0);
--		x900004_NotifyTip( sceneId, selfId, "ret "..ret )	
		if ret == -1 then
			x900004_NotifyTip(sceneId,selfId,"该武魂无法再次延寿。")
		elseif ret == -2 then
			x900004_NotifyTip(sceneId,selfId,"#R你的银两不能支付修理延寿。")
		elseif ret == -4 then
			x900004_NotifyTip(sceneId,selfId,"延寿失败")
		elseif ret == -5 then
			x900004_NotifyTip(sceneId,selfId,"延寿过程中出现未知错误。")
		elseif ret == -6 then
			x900004_NotifyTip(sceneId,selfId,"武魂没有损害，不用延寿。")
		elseif ret == 0 then
			x900004_NotifyTip(sceneId,selfId,"#{WH_090729_37}")
			LuaFnDelAvailableItem(sceneId, selfId, x900004_KfsItem_YanShouDan, 1)
			LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
		end
	else
		x900004_NotifyTip( sceneId, selfId, "#{WH_090729_36}" )	
		return
	end
end
--**********************************
--增加武魂经验
--**********************************
function x900004_AddKfsExp(sceneId,selfId,nExp)
	local nKfsID = LuaFnGetItemTableIndexByIndex( sceneId, selfId, 110 )
	if nKfsID == nil or nKfsID == 0 then
		x900004_NotifyTip( sceneId, selfId,  "#{WH_090729_08}" )
		return 0
	end
	
	local _,nKfsData = LuaFnGetItemCreator(sceneId,selfId,110);
	
	if nKfsData == nil then
	
		local nLevel,nMoreExp = Lua_KfsGetLevelUpExpToLeve(nExp)
		--AddGlobalCountNews( sceneId,"nLevel "..nLevel.." nMoreExp "..nMoreExp)
		--经验修正
		local nAddExp = Lua_KfsInt2Str(0,nExp)	
		--等级修正
		nLevel = Lua_KfsInt2Str(1,nLevel)
		local nFinalKfsData = "&W6021"..nLevel..nAddExp.."0101000000000000000000"
		LuaFnSetEquipItemCreatorEx(sceneId,selfId,110,nFinalKfsData)
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_10}"..nExp )
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_11}"..tonumber(nLevel).."#{WH_090729_12}")
	else
		local Pos1,Pos2,nGrow,nExLevel,nLevel,nKfsExp,nMagic,nExAttrNum,nExAttr,nSkill = strfind(nKfsData,x900004_KfsDataVale)
		if tonumber(nLevel) >= 119 then
			x900004_NotifyTip( sceneId, selfId,"#{WH_090729_09}")
			return 0
		end
		local nAddExp = tonumber(nKfsExp) + nExp
		local nNewLevel,nMoreExp = Lua_KfsGetLevelUpExpToLeve(nAddExp)
		--经验修正
		nAddExp = Lua_KfsInt2Str(0,nAddExp)	
		--等级修正
		nNewLevel = Lua_KfsInt2Str(1,nNewLevel)
		local nFinalKfsData = "&W"..nGrow..nExLevel..nNewLevel..nAddExp..nMagic..nExAttrNum..nExAttr..nSkill
		nFinalKfsData = gsub(nKfsData,x900004_KfsDataVale,nFinalKfsData)
		LuaFnSetEquipItemCreatorEx(sceneId,selfId,110,nFinalKfsData)
		x900004_NotifyTip( sceneId, selfId,"#{WH_090729_10}"..tonumber(nExp) )
		if tonumber(nNewLevel) > tonumber(nLevel) then
			x900004_NotifyTip( sceneId, selfId,"#{WH_090729_11}"..tonumber(nNewLevel).."#{WH_090729_12}")
		end
	end
	LuaFnSendSpecificImpactToUnit(sceneId, selfId, selfId, selfId, 49, 0);
	x900004_RefreshKfs(sceneId,selfId);--提醒客户端武魂属性刷新了
	return 1
end
--**********************************
--经验、等级文本修正
--**********************************
function Lua_KfsInt2Str(nType,nValue)
	if nType == 0 then
		if nValue < 10 then
			nValue = "0000"..nValue
		elseif nValue < 100 and nValue >= 10 then
			nValue = "000"..nValue
		elseif nValue < 1000 and nValue >= 100 then
			nValue = "00"..nValue
		elseif nValue < 10000 and nValue >= 1000 then
			nValue = "0"..nValue
		end
		return nValue
	else
		if nValue < 10 then
			nValue = "00"..nValue
		elseif nValue < 100 and nValue >= 10 then
			nValue = "0"..nValue
		end
		return nValue
	end
end
--**********************************
--获取武魂基础属性
--**********************************
function Lua_KfsGetAttrAndOldAttr(nType,nGrow,nAttrType,nKFS_Level)
	local nBaseAttr,nOldBaseAttr = 0,0
	local nAttrTable = {
		[0] = {2,1,1,1,1},
		[1] = {1,2,1,1,1},
		}
	if nType >= 1 and nType <= 5 and nAttrType ~= nil and nAttrType >= 0 and nAttrType <= 1 then
		nBaseAttr = ceil(nAttrTable[nAttrType][nType] * ((nGrow/100) + 1) * (nKFS_Level/10))
		nOldBaseAttr = ceil(nBaseAttr * ((nGrow/1000) + 1))
	end
	return nBaseAttr,nOldBaseAttr
end
--**********************************
--获取武魂升级所需经验
--**********************************
function Lua_KfsGetLevelUpExpToLeve(nExp)
	local nLevel,nMoreExp = 1,0
	if nExp >= x900004_nExpTable[119] then
		return 119,0
	end
	for i = 1,getn(x900004_nExpTable) do
		if x900004_nExpTable[i] >= nExp then
			nLevel = i - 1;
			nMoreExp = x900004_nExpTable[i] - nExp
			break
		end
	end
	if nLevel < 1 then
		nLevel = 1
	end
	return nLevel,nMoreExp
end
function Lua_KfsGetLevelUpNeedExp(nLevel)
	local nExp = 0
	if x900004_nExpTable[nLevel] ~= nil then
		nExp = x900004_nExpTable[nLevel]
	end
	return nExp
end
