--**********************************
--武魂拓展属性
--**********************************
function Lua_GetKfsFixAttrEx(nExAttr,nIndex)
	if x900004_nAttrExTable[nExAttr] ~= nil then
		return x900004_nAttrExTable[nExAttr][1]
	end
	local iText , iValue = "",0
	local nAttrExType,nAttrExValue = {},{}
	local nAttrExNum = 0;
	if nIndex >= 1 and nIndex <= 7 and nExAttr ~= nil then
		--nExAttr nIndex
		for i = 1,7 do
			nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
			if nAttrExType[i] ~= "0" then
				nAttrExNum = nAttrExNum + 1;
			end
			nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
		end
		local nAttrExIndex = nAttrExType[nIndex]..tostring(nAttrExValue[nIndex])
		if x900004_nAttrExTable[nAttrExIndex] ~= nil then
			iText = x900004_nAttrExTable[nAttrExIndex][1]
			iValue = x900004_nAttrExTable[nAttrExIndex][4]
		end
	end
	if nIndex == 0 and nExAttr ~= nil then
		for i = 1,7 do
			nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
			if nAttrExType[i] ~= "0" then
				nAttrExNum = nAttrExNum + 1;
			end
		end
		return nAttrExNum
	end
	if nIndex >= 100 and nExAttr ~= nil then
		for i = 1,7 do
			nAttrExType[i] = strsub(nExAttr, (i*2) - 1,(i*2) - 1)
			nAttrExValue[i] = tonumber(strsub(nExAttr, i*2,i*2))
		end
		nIndex = nIndex - 100
		local nFinalIndex = nAttrExType[nIndex]..nAttrExValue[nIndex]
		if x900004_nAttrExTable[nFinalIndex] ~= nil then
			return x900004_nAttrExTable[nFinalIndex][2],x900004_nAttrExTable[nFinalIndex][3]
		else
			return 0,-1
		end
	end
	return iText,iValue,nAttrExNum
end
function Lua_GetkfsSkillLevelUp(nSkillID)
	local nNewSkillID,nItemID,nMoney,nLevel = 0,0,0,0
	if x900004_g_nSkillLevelupTab[nSkillID] ~= nil then
