		nItemID = x900004_g_nSkillLevelupTab[nSkillID][2]
		nMoney = x900004_g_nSkillLevelupTab[nSkillID][3]
		nLevel = x900004_g_nSkillLevelupTab[nSkillID][4]
	end  
   return nNewSkillID,nItemID,nMoney,nLevel
end
